sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

	if (isLoading) {
		return;
	}

	var type = g_form.getValue('leave_type');
	var days = parseInt(g_form.getValue('number_of_leave_days'), 10);

	if (type === 'sick' && days > 2) {
		g_form.setMandatory('document_attachment', true);
		g_form.showFieldMsg('document_attachment', 'Upload medical certificate here', 'info');

	} else {
		g_form.setMandatory('document_attachment', false);
		g_form.hideFieldMsg('document_attachment', false);
	}
}
